void _showOwnerProductDialog(BuildContext context, JeebliController ctrl, String restId, {Product? product}) {
  final isEdit = product != null;
  final nameController = TextEditingController(text: product?.name ?? '');
  final priceController = TextEditingController(text: product?.price.toString() ?? '');
  final descController = TextEditingController(text: product?.description ?? '');
  final imageController = TextEditingController(text: product?.imageUrl ?? '');
  String selectedCategory = product?.categoryId ?? 'meals';

  showDialog(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (context, setState) {
        return Directionality(
          textDirection: TextDirection.rtl,
          child: AlertDialog(
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
            title: Text(isEdit ? 'تعديل الوجبة ✏️' : 'إضافة وجبة جديدة 🍔', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  TextField(controller: nameController, decoration: const InputDecoration(labelText: 'اسم الوجبة (مثال: برغر لحم)')),
                  const SizedBox(height: 8),
                  TextField(controller: priceController, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'السعر بالدينار (مثال: 5000)')),
                  const SizedBox(height: 8),
                  TextField(controller: descController, decoration: const InputDecoration(labelText: 'الوصف (المكونات)')),
                  const SizedBox(height: 8),
                  TextField(controller: imageController, decoration: const InputDecoration(labelText: 'رابط الصورة (URL)')),
                  const SizedBox(height: 12),
                  DropdownButtonFormField<String>(
                    value: selectedCategory,
                    items: const [
                      DropdownMenuItem(value: 'meals', child: Text('وجبات سريعة')),
                      DropdownMenuItem(value: 'drinks', child: Text('مشروبات')),
                      DropdownMenuItem(value: 'desserts', child: Text('حلويات')),
                    ],
                    onChanged: (val) {
                      if (val != null) setState(() => selectedCategory = val);
                    },
                    decoration: const InputDecoration(labelText: 'القسم', border: OutlineInputBorder()),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('إلغاء')),
              ElevatedButton(
                onPressed: () {
                  final price = double.tryParse(priceController.text) ?? 0.0;
                  if (nameController.text.trim().isEmpty || price <= 0) return;

                  final imageUrl = imageController.text.trim().isEmpty 
                      ? 'https://cdn-icons-png.flaticon.com/512/3348/3348083.png' 
                      : imageController.text.trim();

                  if (isEdit) {
                    ctrl.updateProduct(
                      product!.id,
                      name: nameController.text.trim(),
                      price: price,
                      description: descController.text.trim(),
                      imageUrl: imageUrl,
                    );
                  } else {
                    ctrl.addProduct(Product(
                      id: 'prod_${DateTime.now().millisecondsSinceEpoch}',
                      restaurantId: restId,
                      categoryId: selectedCategory,
                      name: nameController.text.trim(),
                      description: descController.text.trim(),
                      price: price,
                      imageUrl: imageUrl,
                      isAvailable: true,
                    ));
                  }
                  Navigator.pop(ctx);
                },
                style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFE65100), foregroundColor: Colors.white),
                child: Text(isEdit ? 'حفظ التعديلات' : 'إضافة الآن'),
              ),
            ],
          ),
        );
      }
    ),
  );
}

void _showOwnerDeleteDialog(BuildContext context, JeebliController ctrl, Product product) {
  showDialog(
    context: context,
    builder: (ctx) => Directionality(
      textDirection: TextDirection.rtl,
      child: AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('تأكيد الحذف 🗑️'),
        content: Text('هل أنت متأكد من حذف وجبة "${product.name}" نهائياً من القائمة؟ لا يمكن التراجع عن هذا الإجراء.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('إلغاء')),
          ElevatedButton(
            onPressed: () {
              ctrl.deleteProduct(product.id);
              Navigator.pop(ctx);
            },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red, foregroundColor: Colors.white),
            child: const Text('نعم، احذف الوجبة'),
          ),
        ],
      ),
    ),
  );
}

